// =====================================================================
// ===== V20 PRODUCT LAYER — стабильность, единый UI, рабочие цепочки =====
// Слой поверх V19: бизнес-логика V19 сохранена, здесь — исправления,
// изоляция блоков, новые рендеры и единый Excel-движок.
// =====================================================================
function escH(v){return String(v??'').replace(/[&<>"']/g,s=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[s]))}
function jsArg(v){return escH(JSON.stringify(String(v??'')))}
function plural(n,one,few,many){n=Math.abs(Number(n)||0)%100;const n1=n%10;if(n>10&&n<20)return many;if(n1>1&&n1<5)return few;if(n1===1)return one;return many}
function pl(n,one,few,many){return n+' '+plural(n,one,few,many)}
function money(v){return Math.round(Number(v||0)).toLocaleString('ru-RU')+' сум'}
function num(v){return Math.round(Number(v||0)*1000)/1000}
function currentPageId(){return document.querySelector('.page.active')?.id||'dashboard'}
function isRole(r){return currentUser?.role===r}
function isTop(){return ['Super Admin','CEO','Управляющий сетью'].includes(currentUser?.role)}
function isWorkshopUser(){return currentUser?.role==='Super Admin'||(allowedBranches().includes('Цех')&&currentUser?.role!=='Снабженец'&&currentUser?.role!=='CEO')}
function emptyState(title,text,icon){return `<div class="empty-state"><div class="empty-ico">${icon||'○'}</div><b>${escH(title)}</b>${text?`<div class="mini">${escH(text)}</div>`:''}</div>`}
function safeBlock(name,fn){try{return fn()}catch(e){console.error('[V20 block] '+name,e);return `<div class="card panel block-error"><div><b>Блок «${escH(name)}» временно недоступен</b><div class="mini">Остальная страница работает, данные не удалены.</div></div><button class="btn secondary" onclick="showPage(currentPageId())">Повторить</button></div>`}}
function safeRun(name,fn){try{return fn()}catch(e){console.error('[V20] '+name,e)}}
function statusChip(text,tone){return `<span class="status ${tone||'blue'}">${escH(text)}</span>`}
function statusTone(s){s=String(s||'');if(/оплачено|выплачено|получено|принято|доставлено|выполнено|решено|закрыт|совпало|работает|норма/i.test(s))return'green';if(/просроч|нет на складе|критич|не хватает|недостач|не работает|ремонт/i.test(s))return'red';if(/частич|к оплате|к выплате|в пути|ожида|у снабженца|в работе|комплект|открыт|отправлено|на проверке|обслужив/i.test(s))return'yellow';return'blue'}

// ---------- Toast + индикатор сохранения ----------
let v20ToastTimer=null;
toast=function(msg,type){const t=document.getElementById('toast');if(!t)return;const text=String(msg||'');const kind=type||(/^(не |нет )|не удалось|ошиб|недостат|укажите|выберите|проверьте|сначала|только |нельзя|введите|заполните|доступ|не найден/i.test(text)?'warn':'ok');t.className='toast '+kind;t.innerHTML=`<span class="toast-ico">${kind==='ok'?'<svg viewBox="0 0 24 24"><path d="M5 12.5l4.2 4.2L19 7"/></svg>':'!'}</span><span>${escH(text)}</span>`;void t.offsetWidth;t.classList.add('show');clearTimeout(v20ToastTimer);v20ToastTimer=setTimeout(()=>t.classList.remove('show'),kind==='ok'?2600:3800)};
saveOperationalState=function(){let ok=true;try{localStorage.setItem(OP_KEY,JSON.stringify(opState));localStorage.setItem(OP_KEY+'_users',JSON.stringify(users));localStorage.setItem(OP_KEY+'_inventory',JSON.stringify({sessions:inventorySessions,meta:inventoryDayMeta,drafts:inventoryDrafts,results:inventoryResults}))}catch(e){ok=false;console.warn('state save',e)}const ind=document.getElementById('saveIndicator');if(ind){ind.className='status save-indicator '+(ok?'green':'red');ind.textContent=ok?'● Сохранено '+new Date().toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'}):'● Не сохранено: память браузера заполнена';if(ok){ind.classList.remove('pulse');void ind.offsetWidth;ind.classList.add('pulse')}}if(!ok)toast('Не удалось сохранить: память браузера заполнена. Удалите крупные фото/файлы.','warn');return ok};
let v20SaveTimer=null;function debouncedSave(){clearTimeout(v20SaveTimer);v20SaveTimer=setTimeout(saveOperationalState,400)}

// ---------- Защита от двойного нажатия ----------
document.addEventListener('click',e=>{const b=e.target.closest('.modal-actions .btn.primary,[data-once]');if(!b)return;if(b.dataset.busy==='1'){e.stopImmediatePropagation();e.preventDefault();return}b.dataset.busy='1';b.classList.add('is-busy');setTimeout(()=>{b.dataset.busy='';b.classList.remove('is-busy')},900)},true);

// ---------- Модальные окна: Esc, клик по фону, фокус ----------
openModal=function(id){if(id==='limitModal')syncLimitModal();if(id==='purchaseModal'&&!can('purchases')&&currentUser?.role!=='Super Admin'){toast('Нет доступа к закупкам');return}const m=document.getElementById(id);if(!m)return;m.classList.add('show');document.body.classList.add('modal-open');setTimeout(()=>{const f=m.querySelector('.modal-card input:not([type=hidden]):not([disabled]),.modal-card select,.modal-card textarea');if(f&&window.innerWidth>700)f.focus({preventScroll:true})},60)};
closeModal=function(id){const m=document.getElementById(id);if(!m)return;m.classList.remove('show');if(!document.querySelector('.modal.show'))document.body.classList.remove('modal-open')};
document.addEventListener('keydown',e=>{if(e.key!=='Escape')return;const open=[...document.querySelectorAll('.modal.show')].pop();if(open)closeModal(open.id);else closeMobileNav()});
document.addEventListener('mousedown',e=>{if(e.target.classList?.contains('modal')&&e.target.classList.contains('show'))e.target.dataset.downOnBackdrop='1'});
document.addEventListener('mouseup',e=>{const m=e.target;if(m.classList?.contains('modal')&&m.dataset.downOnBackdrop==='1')closeModal(m.id);document.querySelectorAll('.modal').forEach(x=>x.dataset.downOnBackdrop='')});

// ---------- Диалог подтверждения ----------
function confirmDialog({title,text,okText='Подтвердить',danger=false,html=''}){return new Promise(resolve=>{document.getElementById('infoModalTitle').textContent=title||'Подтверждение';document.getElementById('infoModalSub').textContent='';document.getElementById('infoModalBody').innerHTML=html||`<p class="confirm-text">${escH(text||'')}</p>`;const act=document.getElementById('infoModalActions');act.innerHTML=`<button class="btn secondary" id="cdCancel">Отмена</button><button class="btn ${danger?'danger-solid':'primary'}" id="cdOk">${escH(okText)}</button>`;let done=false;const fin=v=>{if(done)return;done=true;closeModal('infoModal');resetInfoActions();resolve(v)};document.getElementById('cdCancel').onclick=()=>fin(false);document.getElementById('cdOk').onclick=()=>fin(true);const obs=new MutationObserver(()=>{if(!document.getElementById('infoModal').classList.contains('show')){obs.disconnect();fin(false)}});obs.observe(document.getElementById('infoModal'),{attributes:true,attributeFilter:['class']});openModal('infoModal')})}
function resetInfoActions(){const act=document.getElementById('infoModalActions');if(act)act.innerHTML=`<button class="btn secondary" onclick="closeModal('infoModal')">Закрыть</button>`}
function showInfo(title,sub,html,actionsHtml){document.getElementById('infoModalTitle').textContent=title;document.getElementById('infoModalSub').textContent=sub||'';document.getElementById('infoModalBody').innerHTML=html;resetInfoActions();if(actionsHtml)document.getElementById('infoModalActions').insertAdjacentHTML('afterbegin',actionsHtml);openModal('infoModal')}

