saveFinanceEntry=function(){if(!canEditFinance())return;const g=i=>document.getElementById(i).value;const date=g('finDate'),branch=g('finBranch'),type=g('finType'),category=g('finCategory'),amount=Number(g('finAmount')),counterparty=g('finCounterparty').trim(),status=g('finStatus'),note=g('finNote').trim();if(!date||!(amount>0)){toast('Укажите дату и сумму больше нуля');return}if(editingFinanceId){const x=opState.finance.find(v=>v.id===editingFinanceId);if(!x){toast('Запись не найдена');return}const before=`${x.type} • ${money(x.amount)} • ${x.status}`;Object.assign(x,{date,branch,type,category,amount,counterparty,status,note,editedAt:nowISO(),editedBy:currentUser?.name||'—'});if(status==='Частично'&&!x.paidAmount)x.paidAmount=Math.round(amount/2);addOpAudit({branch,action:'Изменена финансовая запись',object:x.id+' • '+category,before,after:`${type} • ${money(amount)} • ${status}`})}else{const id='#FIN-'+String(opState.seq.finance++).padStart(4,'0');opState.finance.unshift({id,date,branch,type,category,amount,counterparty,status,note,time:nowISO(),user:currentUser?.name||'—'});addOpAudit({branch,action:'Финансовая запись',object:category,before:'—',after:money(amount),meta:type+' • '+status})}const wasEdit=!!editingFinanceId;editingFinanceId=null;saveOperationalState();closeModal('financeModal');renderFinanceData();toast(wasEdit?'Запись обновлена':'Финансовая запись сохранена')};
async function archiveFinanceEntry(id,restore){if(!canEditFinance())return;const x=opState.finance.find(v=>v.id===id);if(!x)return;if(!restore){const ok=await confirmDialog({title:'Убрать запись в архив?',text:`${x.category} • ${money(x.amount)}. Запись не удаляется: её можно вернуть, включив фильтр «Архив». В расчётах архивные записи не участвуют.`,okText:'В архив',danger:true});if(!ok)return}x.archived=!restore;x.archivedAt=restore?'':nowISO();addOpAudit({branch:x.branch,action:restore?'Финансовая запись восстановлена':'Финансовая запись в архиве',object:x.id+' • '+x.category,before:money(x.amount),after:restore?'Активна':'Архив'});saveOperationalState();renderFinanceData();toast(restore?'Запись восстановлена':'Запись перенесена в архив')}
renderFinanceData=function(){const body=document.getElementById('financeBody');if(!body)return;safeRun('schema',ensureFinanceStateSchema);safeRun('seed',()=>{seedDemoPayroll();seedDemoFinanceAndRent()});const feb=document.getElementById('financeErrorBanner');if(feb){feb.style.display='none';feb.innerHTML=''}renderCompanyFinanceMaster();safeRun('filters',setupFinanceFilters);
 const g=i=>document.getElementById(i);const from=ceoParseDate(g('financeFrom').value),to=ceoParseDate(g('financeTo').value),bf=g('financeBranchFilter').value,tf=g('financeTypeFilter').value,sf=g('financeStatusFilter')?.value||'Все статусы',q=(g('financeSearch')?.value||'').toLowerCase().trim(),arch=!!g('financeShowArchived')?.checked;
 const list=financeEntriesInRange(from,to,bf,arch).filter(x=>(tf==='Все типы'||x.type===tf)&&(sf==='Все статусы'||x.status===sf)&&(!arch||x.archived)&&(!q||[x.category,x.counterparty,x.note,x.branch,x.id].join(' ').toLowerCase().includes(q))).sort((a,b)=>String(b.date).localeCompare(String(a.date)));
 const edit=canEditFinance();
 body.innerHTML=list.map(x=>`<tr class="${x.archived?'row-archived':''}"><td>${escH(new Date(x.date+'T12:00:00').toLocaleDateString('ru-RU'))}</td><td>${escH(x.branch)}</td><td>${statusChip(x.type,x.type==='Доход'?'green':x.type==='Долг'?'yellow':'red')}</td><td><b>${escH(x.category)}</b></td><td class="num-col ${x.type==='Доход'?'good':x.type==='Расход'?'bad':''}"><b>${money(x.amount)}</b></td><td>${escH(x.counterparty||'—')}</td><td class="cell-wrap">${escH(x.note||'—')}</td><td>${statusChip(x.status,statusTone(x.status))}${x.ceoApproved&&!['Оплачено','Закрыт'].includes(x.status)?'<div class="mini good">одобрено CEO</div>':''}</td><td>${escH(x.user||'—')}</td><td class="row-actions">${edit?(x.archived?`<button class="btn secondary sm" onclick="archiveFinanceEntry(${jsArg(x.id)},true)">Вернуть</button>`:`${x.salaryId?'<span class="mini" title="Изменяется через вкладку «Зарплаты»">через зарплаты</span>':`<button class="btn secondary sm" onclick="openFinanceModal(${jsArg(x.id)})">Изменить</button>`}<button class="btn ghost sm" title="В архив" onclick="archiveFinanceEntry(${jsArg(x.id)})">В архив</button>`):''}</td></tr>`).join('')||`<tr><td colspan="10">${emptyState('Записей нет','Измените период или фильтры.','₿')}</td></tr>`;
 g('financeSummary').innerHTML=safeBlock('Сводка периода',()=>{const all=financeEntriesInRange(from,to,bf);const sum=(f)=>all.filter(f).reduce((a,x)=>a+Number(x.amount||0),0);const income=sum(x=>x.type==='Доход'),exp=sum(x=>x.type==='Расход'),debt=sum(x=>x.type==='Долг'&&!['Закрыт','Оплачено'].includes(x.status)),toPay=all.filter(x=>x.type==='Расход'&&['К оплате','Частично','Открыт'].includes(x.status)).reduce((a,x)=>a+Math.max(0,Number(x.amount||0)-financePaidPart(x)),0);const month=new Date().toISOString().slice(0,7);const sal=(opState.salaries||[]).filter(x=>x.month===month&&(bf==='Все филиалы'||x.branch===bf));const salG=sal.reduce((a,x)=>a+Number(x.gross||0),0),salR=sal.reduce((a,x)=>a+Number(x.remaining||0),0);let rentD=0,rentP=0;(opState.rentContracts||[]).filter(c=>bf==='Все филиалы'||c.branch===bf).forEach(c=>(c.schedule||[]).filter(m=>m.month===month).forEach(m=>{rentD+=Number(m.due||0);rentP+=Number(m.paid||0)}));const card=(l,v,cls,sub,on)=>`<div class="card ceo-kpi ${on?'dash-click':''}" ${on?`onclick="${on}"`:''}><div class="mini">${l}</div><div class="big ${cls||''}">${ceoMoneyShort(v)}</div><div class="mini">${sub||''}</div></div>`;return `<div class="finance-summary-grid six">${card('Доходы',income,'good','за период')}${card('Расходы',exp,'bad','за период')}${card('Долги поставщикам',debt,'warn','открытые')}${card('К оплате',toPay,'warn','счета и расходы')}${card('Зарплаты • '+month,salG,'',`остаток ${ceoMoneyShort(salR)}`,"switchFinanceView('salary')")}${card('Аренда • '+month,rentD,'',`оплачено ${ceoMoneyShort(rentP)}`,"switchFinanceView('rent')")}</div>`})};

