function showSalaryDetails(id){const x=(opState.salaries||[]).find(v=>v.id===id);if(!x)return;const rows=[['Сотрудник',x.employeeName],['Должность',x.role||'—'],['Филиал',x.branch],['Период',x.month],['Способ расчёта',x.calcType],['Оклад / база',money(x.base)],['Часы / смены',x.units||'—'],['Ставка',x.rate?money(x.rate):'—'],['Процент / KPI',x.percent?x.percent+'%':'—'],['Бонус',money(x.bonus)],['Аванс',money(x.advance)],['Удержание',money(x.deduction)],['Начислено',money(x.gross)],['Выплачено (с авансом)',money(Number(x.paid||0)+Number(x.advance||0))],['Остаток',money(x.remaining)],['Статус',x.status],['Комментарий',x.note||'—'],['Ввёл',x.user||'—']];showInfo('Начисление • '+x.employeeName,x.id,`<div class="kv-list">${rows.map(r=>`<div><span>${escH(r[0])}</span><b>${escH(r[1])}</b></div>`).join('')}</div>`)}

