function obligationTarget(o){if(o.source==='finance')return opState.finance.find(v=>v.id===o.ref);if(o.source==='salary')return opState.salaries.find(v=>v.id===o.ref);if(o.source==='purchase')return opState.purchases.find(v=>v.id===o.ref);if(o.source==='rent'){const c=opState.rentContracts.find(v=>v.id===o.ref);return c?.schedule?.find(v=>v.month===o.subref)}return null}
function obligationKind(x){const c=String(x.category||'');if(x.type==='Долг')return /поставщ/i.test(c)?'Поставщик':'Долг';if(/налог/i.test(c))return'Налоги';if(/коммун/i.test(c))return'Коммунальные';if(/закуп/i.test(c))return'Закупка';return c||'Расход'}
ceoObligations=function(){safeRun('obl bootstrap',()=>{ensureFinanceStateSchema();seedDemoFinanceAndRent();seedDemoPayroll()});const out=[],horizon=new Date(Date.now()+35*86400000);
 activeFinance().forEach(x=>{if(x.type==='Доход'||['Оплачено','Закрыт','Получено'].includes(x.status)||x.ceoHidden)return;if(x.salaryId)return;let amount=0;if(x.type==='Долг')amount=Number(x.amount||0);else if(x.type==='Расход')amount=Math.max(0,Number(x.amount||0)-financePaidPart(x));if(amount<=0)return;if(x.category==='Аренда'&&String(x.id).startsWith('#FIN-RENT-D'))return;out.push({key:'finance:'+x.id,source:'finance',ref:x.id,type:obligationKind(x),branch:x.branch||'Вся сеть',due:x.dueDate||x.date||'',amount,who:x.counterparty||'—',desc:x.note||x.category||'Финансовое обязательство',approved:!!x.ceoApproved,status:x.status||'К оплате'})});
 (opState.salaries||[]).forEach(x=>{const rem=Number(x.remaining||0);if(rem<=0||x.ceoHidden)return;out.push({key:'salary:'+x.id,source:'salary',ref:x.id,type:'Зарплата',branch:x.branch||'Вся сеть',due:(x.month||'')+'-25',amount:rem,who:x.employeeName||'Сотрудник',desc:`${x.role||'Сотрудник'} • ${x.month||''} • остаток к выплате`,approved:!!x.ceoApproved,status:x.status||'К выплате'})});
 (opState.rentContracts||[]).forEach(c=>(c.schedule||[]).forEach(m=>{const rem=Math.max(0,Number(m.due||0)-Number(m.paid||0));if(rem<=0||m.ceoHidden)return;const dd=new Date((m.dueDate||'2999-12-31')+'T00:00:00');if(dd>horizon)return;out.push({key:`rent:${c.id}:${m.month}`,source:'rent',ref:c.id,subref:m.month,type:'Аренда',branch:c.branch||'—',due:m.dueDate||'',amount:rem,who:c.landlord||'Арендодатель',desc:`Договор ${c.contractNo||c.id} • ${rentMonthLabel(m.month)}`,approved:!!m.ceoApproved,status:dd<new Date(new Date().toDateString())?'Просрочка':m.paid>0?'Частично':'К оплате'})}));
 (opState.purchases||[]).forEach(p=>{if(!(Number(p.amount)>0)||p.paid||p.cancelled||p.ceoHidden)return;out.push({key:'purchase:'+p.id,source:'purchase',ref:p.id,type:'Закупка',branch:'Цех',due:p.due?String(p.due).slice(0,10):'',amount:Number(p.amount),who:p.supplier||p.buyer||'Поставщик',desc:`${p.id} • ${p.product} ${p.qty} ${p.unit} • ${p.status}`,approved:!!p.ceoApproved,status:'К оплате'})});
 return out.sort((a,b)=>String(a.due||'9999').localeCompare(String(b.due||'9999'))||b.amount-a.amount)};
function ceoCanAct(){return currentUser?.role==='CEO'||currentUser?.role==='Super Admin'}
function ceoSetApproval(key,val){if(!ceoCanAct()){toast('Доступно CEO или IT-отделу');return}const o=ceoFindObligation(key);if(!o){toast('Обязательство не найдено — обновите страницу');return}const x=obligationTarget(o);if(!x)return;x.ceoApproved=val;x.ceoApprovedAt=val?nowISO():'';x.ceoApprovedBy=val?currentUser.name:'';addOpAudit({branch:o.branch,action:val?'CEO одобрил платёж':'CEO снял одобрение',object:o.type,before:val?'Ожидает':'Одобрено',after:val?'Одобрено':'Ожидает',meta:o.who+' • '+money(o.amount)});saveOperationalState();rerenderCEOFinance();toast(val?'Платёж одобрен':'Одобрение снято')}
ceoApproveObligation=key=>ceoSetApproval(key,true);ceoUnapproveObligation=key=>ceoSetApproval(key,false);
ceoHideObligation=async function(key){if(!ceoCanAct()){toast('Доступно CEO или IT-отделу');return}const o=ceoFindObligation(key);if(!o)return;const ok=await confirmDialog({title:'Убрать из Центра платежей?',text:`${o.type} • ${o.who} • ${money(o.amount)}. Исходная бухгалтерская запись остаётся в системе и в финансовых отчётах — она просто не будет показываться в списке CEO.`,okText:'Убрать из списка'});if(!ok)return;const x=obligationTarget(o);if(x){x.ceoHidden=true;x.ceoHiddenAt=nowISO();x.ceoHiddenBy=currentUser.name}addOpAudit({branch:o.branch,action:'CEO убрал обязательство из центра платежей',object:o.type,before:o.approved?'Одобрено':'Ожидает',after:'Скрыто CEO',meta:o.who+' • '+money(o.amount)});saveOperationalState();rerenderCEOFinance();toast('Убрано из списка CEO. Запись сохранена в финансах.')};
function ceoRestoreHidden(){if(!ceoCanAct())return;let n=0;(opState.finance||[]).forEach(x=>{if(x.ceoHidden){x.ceoHidden=false;n++}});(opState.salaries||[]).forEach(x=>{if(x.ceoHidden){x.ceoHidden=false;n++}});(opState.purchases||[]).forEach(x=>{if(x.ceoHidden){x.ceoHidden=false;n++}});(opState.rentContracts||[]).forEach(c=>(c.schedule||[]).forEach(m=>{if(m.ceoHidden){m.ceoHidden=false;n++}}));saveOperationalState();rerenderCEOFinance();toast(n?`Возвращено в список: ${n}`:'Скрытых обязательств нет')}
ceoPayObligation=async function(key){if(!ceoCanAct()){toast('Оплата доступна CEO или IT-отделу');return}const o=ceoFindObligation(key);if(!o){toast('Обязательство уже закрыто');rerenderCEOFinance();return}if(!o.approved){toast('Сначала одобрите платёж');return}const cash=companyFinancePosition().cash;if(!(cash>=o.amount)){toast(`Недостаточно денег: есть ${money(cash)}, нужно ${money(o.amount)}`,'warn');return}
 const ok=await confirmDialog({title:'Подтвердить оплату',okText:'Оплатить '+ceoMoneyShort(o.amount),html:`<div class="kv-list"><div><span>Тип</span><b>${escH(o.type)}</b></div><div><span>Кому</span><b>${escH(o.who)}</b></div><div><span>Основание</span><b>${escH(o.desc)}</b></div><div><span>Сумма</span><b>${money(o.amount)}</b></div><div><span>Деньги сейчас</span><b>${money(cash)}</b></div><div><span>Останется после оплаты</span><b class="good">${money(cash-o.amount)}</b></div></div>`});if(!ok)return;
 const again=ceoFindObligation(key);if(!again||companyFinancePosition().cash<again.amount){toast('Оплата не проведена: данные изменились или денег недостаточно','warn');rerenderCEOFinance();return}
 const x=obligationTarget(o),now=nowISO();if(!x)return;
 if(o.source==='finance'){x.status=x.type==='Долг'?'Закрыт':'Оплачено';x.paidAmount=Number(x.amount||0);x.ceoPaidAt=now;x.ceoPaidBy=currentUser.name;if(x.type==='Долг'){const id='#FIN-'+String(opState.seq.finance++).padStart(4,'0');opState.finance.unshift({id,date:ceoDateKey(new Date()),branch:x.branch,type:'Расход',category:'Погашение долга',amount:o.amount,counterparty:x.counterparty,status:'Оплачено',note:'Погашение '+x.id+' после одобрения CEO',time:now,user:currentUser.name,linkedDebt:x.id})}}
 else if(o.source==='salary'){const rem=Number(x.remaining||0);x.paid=Number(x.paid||0)+rem;x.remaining=0;x.status='Выплачено';x.ceoPaidAt=now;const fin=opState.finance.find(v=>v.salaryId===x.id);if(fin){fin.status='Оплачено';fin.paidAmount=Number(fin.amount||0)}}
 else if(o.source==='rent'){const rem=Math.max(0,Number(x.due||0)-Number(x.paid||0));x.paid=Number(x.paid||0)+rem;x.payments=x.payments||[];x.payments.push({amount:rem,date:ceoDateKey(new Date()),note:'Оплата после одобрения CEO',user:currentUser.name,time:now});x.ceoPaidAt=now}
 else if(o.source==='purchase'){x.paid=true;x.paidAt=now;const id='#FIN-'+String(opState.seq.finance++).padStart(4,'0');opState.finance.unshift({id,date:ceoDateKey(new Date()),branch:'Цех',type:'Расход',category:'Закуп',amount:o.amount,counterparty:x.supplier||x.buyer||'Поставщик',status:'Оплачено',note:`Оплата закупа ${x.id} • ${x.product}`,time:now,user:currentUser.name,purchaseId:x.id})}
 addOpAudit({branch:o.branch,action:'Платёж подтверждён CEO',object:o.type,before:'Одобрено',after:'Оплачено',meta:o.who+' • '+money(o.amount)});saveOperationalState();rerenderCEOFinance();toast('Оплата проведена • '+money(o.amount))};
function rerenderCEOFinance(){if(currentPageId()==='ceo')renderCEO();else{safeRun('obl',renderCEOObligations);renderCompanyFinanceMaster()}if(currentPageId()==='financeData')safeRun('fin',renderFinanceData)}
renderCEOObligations=function(){const root=document.getElementById('ceoObligations');if(!root)return;root.innerHTML=safeBlock('Центр платежей',()=>{const list=ceoObligations(),p=companyFinancePosition(),act=ceoCanAct();const approved=list.filter(x=>x.approved),soon=new Date(Date.now()+7*86400000),urgent=list.filter(x=>x.status==='Просрочка'||(x.due&&new Date(x.due+'T00:00:00')<=soon)),total=list.reduce((a,x)=>a+x.amount,0);let running=p.cash;
 const rows=list.map(o=>{const enough=running>=o.amount,after=running-o.amount;if(o.approved&&enough)running=after;const overdue=o.status==='Просрочка'||(o.due&&new Date(o.due+'T00:00:00')<new Date(new Date().toDateString()));return `<tr class="${overdue?'row-overdue':''}"><td data-label="Тип"><div class="cv"><b>${escH(o.type)}</b><div class="mini">${escH(o.status)}</div></div></td><td data-label="Филиал"><div class="cv">${escH(o.branch)}</div></td><td data-label="Кому / основание"><div class="cv"><b>${escH(o.who)}</b><div class="mini obligation-desc">${escH(o.desc)}</div></div></td><td data-label="Срок" class="${overdue?'bad':''}"><div class="cv">${o.due?escH(new Date(o.due+'T00:00:00').toLocaleDateString('ru-RU')):'—'}${overdue?'<div class="mini bad">просрочено</div>':''}</div></td><td data-label="Сумма" class="num-col"><div class="cv"><b>${money(o.amount)}</b></div></td><td data-label="Деньги" class="${enough?'obligation-money-ok':'obligation-money-no'}"><div class="cv">${enough?'Хватает':'Не хватает'}<div class="mini">${enough?'останется '+money(after):'нужно ещё '+money(o.amount-running)}</div></div></td><td data-label="Статус"><div class="cv">${statusChip(o.approved?'Одобрено':'Ждёт CEO',o.approved?'green':'yellow')}</div></td><td data-label="Действие"><div class="cv"><div class="obligation-actions">${act?`${!o.approved?`<button class="btn secondary sm" onclick="ceoApproveObligation(${jsArg(o.key)})">Одобрить</button>`:`<button class="btn secondary sm" onclick="ceoUnapproveObligation(${jsArg(o.key)})">Снять одобрение</button>`}<button class="btn primary sm" data-once ${!o.approved||!enough?'disabled':''} title="${!o.approved?'Сначала одобрите':!enough?'Недостаточно денег компании':'Провести оплату'}" onclick="ceoPayObligation(${jsArg(o.key)})">Оплатить</button><button class="btn ghost sm" title="Убрать из списка CEO — запись в финансах сохранится" onclick="ceoHideObligation(${jsArg(o.key)})">Убрать</button>`:'<span class="mini">только просмотр</span>'}</div></div></td></tr>`}).join('');
 const hiddenCount=(opState.finance||[]).filter(x=>x.ceoHidden&&!['Оплачено','Закрыт'].includes(x.status)).length+(opState.salaries||[]).filter(x=>x.ceoHidden&&x.remaining>0).length+(opState.purchases||[]).filter(x=>x.ceoHidden&&!x.paid).length+(opState.rentContracts||[]).reduce((a,c)=>a+(c.schedule||[]).filter(m=>m.ceoHidden&&m.paid<m.due).length,0);
 return `<div class="ceo-obligation-summary"><div class="ceo-obligation-kpi"><small>Предстоящие платежи</small><b>${money(total)}</b><div class="mini">${pl(list.length,'платёж','платежа','платежей')} • ближайшие 35 дней</div></div><div class="ceo-obligation-kpi warn"><small>Одобрено CEO</small><b>${money(approved.reduce((a,x)=>a+x.amount,0))}</b><div class="mini">${pl(approved.length,'платёж','платежа','платежей')} к оплате</div></div><div class="ceo-obligation-kpi danger"><small>Срочно / просрочено</small><b>${money(urgent.reduce((a,x)=>a+x.amount,0))}</b><div class="mini">${pl(urgent.length,'платёж','платежа','платежей')} в течение 7 дней</div></div><div class="ceo-obligation-kpi good"><small>Деньги компании</small><b>${money(p.cash)}</b><div class="mini ${p.cash-total<0?'bad':''}">после всех платежей: ${money(p.cash-total)}</div></div></div><div class="table-wrap"><table class="ceo-obligation-table"><thead><tr><th>Тип</th><th>Филиал</th><th>Кому / основание</th><th>Срок</th><th class="num-col">Сумма</th><th>Хватает денег?</th><th>Статус</th><th>Действие</th></tr></thead><tbody>${rows||`<tr><td colspan="8">${emptyState('Открытых обязательств нет','Все предстоящие платежи закрыты.','✓')}</td></tr>`}</tbody></table></div>${hiddenCount&&act?`<div class="mini" style="margin-top:10px">Скрыто из списка: ${hiddenCount}. <button class="link-btn" onclick="ceoRestoreHidden()">Вернуть в список</button></div>`:''}`})};

function obligationsByType(){const list=ceoObligations(),by={};list.forEach(o=>{const k=o.type==='Поставщик'||o.type==='Долг'?'Поставщики / долги':o.type;by[k]=(by[k]||0)+o.amount});return by}

