 const allBranches=chartBranches(),selected=branchEl?.value||'Все филиалы',bnames=selected==='Все филиалы'?allBranches:allBranches.filter(b=>b===selected);
 let cur=null,prev=null,pf=null,pt=null;try{cur=ceoPeriodData(bnames,from,to);[pf,pt]=ceoPrevRange(from,to);prev=ceoPeriodData(bnames,pf,pt)}catch(e){console.error('ceo period',e)}
 const sections=[];
