startPurchase=function(product,qty,reason){if(!can('purchases')&&currentUser?.role!=='Super Admin'){toast('Нет доступа к закупкам');return}const sup=document.getElementById('purchaseSupplier');if(sup)sup.innerHTML=supplierCompanies.map(s=>`<option>${escH(s.name)}</option>`).join('')+'<option>Другой поставщик</option>';document.getElementById('purchaseProduct').value=product||'';document.getElementById('purchaseQty').value=qty?num(qty):'';document.getElementById('purchaseAmount').value='';document.getElementById('purchaseComment').value='';if(reason)document.getElementById('purchaseReason').value=reason;const u=product?unitFor('Цех',product):'';if(u&&[...document.getElementById('purchaseUnit').options].some(o=>o.value===u))document.getElementById('purchaseUnit').value=u;const d=new Date(Date.now()+86400000);d.setMinutes(d.getMinutes()-d.getTimezoneOffset());document.getElementById('purchaseDue').value=d.toISOString().slice(0,16);syncProductControlsFor('Цех');openModal('purchaseModal')};
function syncProductControlsFor(branch){const dl=document.getElementById('productCatalogList');if(dl)dl.innerHTML=branchProducts(branch).map(p=>`<option value="${escH(p.n)}">${escH(p.c)} • ${escH(p.u)}</option>`).join('')}
createPurchase=function(){const g=i=>document.getElementById(i);const product=g('purchaseProduct').value.trim(),qty=Number(g('purchaseQty').value),unit=g('purchaseUnit').value,buyer=g('purchaseBuyer').value,reason=g('purchaseReason').value,due=g('purchaseDue').value,comment=g('purchaseComment').value.trim(),supplier=g('purchaseSupplier')?.value||'',amount=Number(g('purchaseAmount')?.value||0);if(!product||!(qty>0)){toast('Укажите товар и количество');return}if(!productExists('Цех',product)){toast('Товар не найден в каталоге цеха: '+product);return}const id='#PUR-'+String(opState.seq.purchase++).padStart(4,'0');opState.purchases.unshift({id,time:nowISO(),product,qty,unit,buyer,reason,due,comment,supplier,amount:amount>0?amount:0,paid:false,status:'У снабженца',user:currentUser?.name||'—'});addOpAudit({branch:'Цех',action:'Создан закуп',object:product,before:'—',after:qty+' '+unit,product,qty,meta:buyer+' • '+supplier+' • '+reason});saveOperationalState();closeModal('purchaseModal');render();toast(id+' отправлен снабженцу'+(amount>0?' • сумма попала в Центр платежей CEO':''))};
function purchaseInTransit(id){const x=opState.purchases.find(z=>z.id===id);if(!x||x.status!=='У снабженца')return;x.status='В пути';x.shippedAt=nowISO();x.shippedBy=currentUser?.name||'—';addOpAudit({branch:'Цех',action:'Закуп в пути',object:x.product,before:'У снабженца',after:'В пути',meta:x.id+' • '+(x.supplier||'')});saveOperationalState();render();toast(id+': товар в пути на цех')}
const _markPurchaseDeliveredV19=markPurchaseDelivered;
markPurchaseDelivered=function(id){const x=opState.purchases.find(z=>z.id===id);if(!x||x.status==='Доставлено')return;if(!isWorkshopUser()){toast('Приход на цех подтверждает склад / цех');return}_markPurchaseDeliveredV19(id);if(x.status==='Доставлено'){opState.receipts??=[];const rid='#PR-'+receiptSeq++;opState.receipts.unshift({id:rid,time:x.deliveredAt||nowISO(),branch:'Цех',source:x.supplier||'Поставщик',doc:x.id,comment:'Приход по закупу '+x.id,user:currentUser?.name||'—',items:[{product:x.product,qty:x.qty,unit:x.unit}]});x.receiptId=rid;saveOperationalState();render()}};
function purchaseCancel(id){const x=opState.purchases.find(z=>z.id===id);if(!x||x.status==='Доставлено')return;confirmDialog({title:'Отменить закуп '+id+'?',text:'Закуп останется в истории со статусом «Отменён».',okText:'Отменить закуп',danger:true}).then(ok=>{if(!ok)return;x.status='Отменён';x.cancelled=true;addOpAudit({branch:'Цех',action:'Закуп отменён',object:x.product,before:'—',after:'Отменён',meta:x.id});saveOperationalState();render();toast('Закуп отменён')})}
function renderPurchasesV20(){const pb=document.getElementById('purchasesBody');if(!pb)return;const flow=document.querySelector('#purchases .flow');if(flow)flow.outerHTML=`<div class="flow-steps" id="purchaseFlow"></div>`;const pf=document.getElementById('purchaseFlow');const list=(opState.purchases||[]).filter(()=>currentUser?.role==='Super Admin'||can('purchases'));const cnt=s=>list.filter(x=>x.status===s).length;if(pf)pf.innerHTML=[['Создано → у снабженца',cnt('У снабженца')],['В пути на цех',cnt('В пути')],['Принято на цех',cnt('Доставлено')]].map((s,i)=>`<div class="flow-step-card"><span class="step-n">${i+1}</span><div><b>${s[1]}</b><small>${s[0]}</small></div></div>`).join('<span class="flow-arrow">→</span>');const buyer=currentUser?.role==='Снабженец'||currentUser?.role==='Super Admin',ws=isWorkshopUser();
 pb.innerHTML=list.map(x=>{const acts=[];if(x.status==='У снабженца'&&buyer)acts.push(`<button class="btn secondary sm" onclick="purchaseInTransit(${jsArg(x.id)})">Купил — в пути</button>`);if(['У снабженца','В пути'].includes(x.status)&&ws)acts.push(`<button class="btn primary sm" data-once onclick="markPurchaseDelivered(${jsArg(x.id)})">Принять на цех</button>`);if(['У снабженца','В пути'].includes(x.status)&&(ws||buyer))acts.push(`<button class="btn ghost sm" onclick="purchaseCancel(${jsArg(x.id)})">Отменить</button>`);return `<tr><td><b>${escH(x.id)}</b></td><td>${displayDate(x.time)}</td><td><b>${escH(x.product)}</b><div class="mini">${escH(x.supplier||'Поставщик не указан')}${Number(x.amount)>0?' • '+money(x.amount)+(x.paid?' • оплачено':' • ждёт оплаты CEO'):''}</div></td><td>${num(x.qty)} ${escH(x.unit)}</td><td>${escH(x.buyer)}</td><td>${escH(x.reason)}</td><td>${x.due?escH(new Date(x.due).toLocaleString('ru-RU',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})):'—'}</td><td>${statusChip(x.status==='Доставлено'?'Принято на цех':x.status,x.status==='Отменён'?'red':statusTone(x.status))}</td><td class="row-actions">${acts.join('')||'—'}</td></tr>`}).join('')||`<tr><td colspan="9">${emptyState('Закупов пока нет','Закуп создаётся из Цеха, когда товара не хватает для заявок.','🛒')}</td></tr>`}

// ---------- Заявки филиалов → Цех → в пути → принято ----------
const REQ_OPEN=['Новая','Комплектация','Частично','Нет на складе'];
function requestTransfers(q){return (opState.transfers||[]).filter(t=>t.requestId===q.id||t.reason==='Заявка '+q.id)}
function requestStage(q){const tr=requestTransfers(q),inTransit=tr.filter(t=>t.status==='В пути').length,received=tr.filter(t=>t.status==='Получено').reduce((a,t)=>a+Number(t.qty||0),0);if(q.status==='Выполнено'||q.status==='Принято')return 'Принято';if(q.status==='Нет на складе')return 'Нет на складе';if(q.status==='Комплектация')return 'Комплектация';if(q.status==='Новая')return 'Новая';if(inTransit)return q.sent>=q.qty?'В пути':'Частично в пути';if(received>=q.qty)return 'Принято';if(q.status==='Частично')return 'Частично';return q.status}
function requestStartPicking(id){const q=opState.requests.find(x=>x.id===id);if(!q||q.status!=='Новая')return;q.status='Комплектация';q.pickedBy=currentUser?.name||'—';addOpAudit({branch:'Цех',action:'Заявка взята в комплектацию',object:q.product,before:'Новая',after:'Комплектация',meta:q.id+' • '+q.branch});saveOperationalState();render();toast(q.id+' взята в комплектацию')}
fulfillRequest=function(id){const q=opState.requests.find(x=>x.id===id);if(!q)return;if(!isWorkshopUser()){toast('Отправку делает цех');return}const available=balanceOf('Цех',q.product);if(available<=0){q.status='Нет на складе';addOpAudit({branch:'Цех',action:'Заявка не выполнена',object:q.product,before:'0 '+q.unit,after:'Нет на складе',product:q.product,meta:q.id});saveOperationalState();render();toast('На цехе нет товара — можно оформить закуп','warn');return}const send=num(Math.min(available,q.qty-q.sent));if(send<=0)return;const r=adjustBalance('Цех',q.product,-send);const trId='#TR-'+String(opState.seq.transfer++).padStart(4,'0');opState.transfers.unshift({id:trId,time:nowISO(),from:'Цех',to:q.branch,product:q.product,qty:send,unit:q.unit,reason:'Заявка '+q.id,requestId:q.id,user:currentUser?.name||'—',status:'В пути'});q.sent=num(q.sent+send);q.status=q.sent>=q.qty?'Отправлено':'Частично';addOpAudit({branch:'Цех',action:'Заявка обработана / отправка',object:q.product,before:r.before+' '+q.unit,after:r.after+' '+q.unit,product:q.product,qty:-send,balanceAfter:r.after,meta:q.id+' → '+q.branch});saveOperationalState();render();toast(`Отправлено ${send} ${q.unit} • ${trId} в пути`)};
const _confirmTransferV19=confirmTransfer;
confirmTransfer=function(id){const x=opState.transfers.find(z=>z.id===id);_confirmTransferV19(id);if(!x||x.status!=='Получено')return;const qid=x.requestId||(String(x.reason||'').startsWith('Заявка ')?String(x.reason).slice(7):'');const q=opState.requests.find(r=>r.id===qid);if(q){const tr=requestTransfers(q),recv=tr.filter(t=>t.status==='Получено').reduce((a,t)=>a+Number(t.qty||0),0),transit=tr.some(t=>t.status==='В пути');if(recv>=q.qty&&!transit){q.status='Принято';q.receivedAt=nowISO();addOpAudit({branch:q.branch,action:'Заявка принята филиалом',object:q.product,before:'В пути',after:'Принято',meta:q.id});saveOperationalState()}render()}};
function acceptRequest(id){const q=opState.requests.find(x=>x.id===id);if(!q)return;const tr=requestTransfers(q).filter(t=>t.status==='В пути');if(!tr.length){toast('Нет отправок в пути по этой заявке');return}tr.forEach(t=>confirmTransfer(t.id));toast('Заявка '+id+': товар принят')}
function renderRequestsV20(){const rb=document.getElementById('requestsBody');if(!rb)return;const ws=isWorkshopUser();const list=(opState.requests||[]).filter(x=>currentUser?.role==='Super Admin'||allowedBranches().includes(x.branch)||allowedBranches().includes('Цех'));const head=document.querySelector('#requests .page-head');if(head&&!document.getElementById('requestFlow'))head.insertAdjacentHTML('afterend','<div class="flow-steps" id="requestFlow"></div><div class="filters"><select id="requestStageFilter" onchange="renderRequestsV20()"><option value="open">Открытые</option><option value="all">Все</option><option value="done">Принятые</option></select><input id="requestSearch" placeholder="Поиск: товар, филиал, №" oninput="renderRequestsV20()"></div>');const stages=list.map(q=>[q,requestStage(q)]);const c=s=>stages.filter(x=>s.includes(x[1])).length;const fl=document.getElementById('requestFlow');if(fl)fl.innerHTML=[['Новые заявки',c(['Новая'])],['Комплектация',c(['Комплектация','Частично','Нет на складе'])],['В пути',c(['В пути','Частично в пути'])],['Принято филиалом',c(['Принято'])]].map((s,i)=>`<div class="flow-step-card"><span class="step-n">${i+1}</span><div><b>${s[1]}</b><small>${s[0]}</small></div></div>`).join('<span class="flow-arrow">→</span>');const f=document.getElementById('requestStageFilter')?.value||'open',q=(document.getElementById('requestSearch')?.value||'').toLowerCase();
 rb.innerHTML=stages.filter(([r,s])=>(f==='all'||(f==='done'?s==='Принято':s!=='Принято'))&&(!q||(r.id+' '+r.product+' '+r.branch).toLowerCase().includes(q))).map(([x,s])=>{const acts=[];const mine=allowedBranches().includes(x.branch)||currentUser?.role==='Super Admin';if(ws){if(s==='Новая')acts.push(`<button class="btn secondary sm" onclick="requestStartPicking(${jsArg(x.id)})">В комплектацию</button>`);if(['Новая','Комплектация','Частично','Нет на складе'].includes(s)&&x.sent<x.qty)acts.push(`<button class="btn primary sm" data-once onclick="fulfillRequest(${jsArg(x.id)})">${x.sent>0?'Отправить остаток':'Отправить'}</button>`);if(s==='Нет на складе'&&can('purchases'))acts.push(`<button class="btn ghost sm" onclick="startPurchase(${jsArg(x.product)},${Number(x.qty-x.sent)},'Дефицит по заявкам филиалов')">В закупку</button>`)}if(mine&&/в пути/i.test(s))acts.push(`<button class="btn primary sm" data-once onclick="acceptRequest(${jsArg(x.id)})">Принять товар</button>`);const tr=requestTransfers(x),recv=tr.filter(t=>t.status==='Получено').reduce((a,t)=>a+Number(t.qty||0),0);return `<tr class="${x.priority==='Срочный'&&s!=='Принято'?'row-urgent':''}"><td><b>${escH(x.id)}</b></td><td>${displayDate(x.time)}</td><td>${escH(x.branch)}</td><td><b>${escH(x.product)}</b></td><td>${num(x.qty)} ${escH(x.unit)}</td><td>${x.priority==='Срочный'?statusChip('Срочный','red'):'<span class="mini">Обычный</span>'}</td><td class="cell-wrap">${escH(x.comment||'—')}</td><td>${statusChip(s,s==='Новая'?'blue':s==='Комплектация'?'violet':statusTone(s))}<div class="mini">отправлено ${num(x.sent)} • принято ${num(recv)}</div></td><td class="row-actions">${acts.join('')||'—'}</td></tr>`}).join('')||`<tr><td colspan="9">${emptyState(f==='open'?'Открытых заявок нет':'Заявок нет','Филиал создаёт заявку кнопкой «Создать заявку».','✓')}</td></tr>`}
function renderTransfersV20(){const tf=document.getElementById('transfersBody');if(!tf)return;const list=(opState.transfers||[]).filter(x=>currentUser?.role==='Super Admin'||allowedBranches().includes(x.from)||allowedBranches().includes(x.to));tf.innerHTML=list.map(x=>`<tr><td><b>${escH(x.id)}</b></td><td>${displayDate(x.time)}</td><td>${escH(x.from)}</td><td>${escH(x.to)}</td><td><b>${escH(x.product)}</b></td><td>${num(x.qty)} ${escH(x.unit)}</td><td>${escH(x.reason)}</td><td>${escH(x.user)}${x.receivedBy?`<div class="mini">принял: ${escH(x.receivedBy)}</div>`:''}</td><td>${statusChip(x.status,statusTone(x.status))}${x.status==='В пути'&&(currentUser?.role==='Super Admin'||allowedBranches().includes(x.to))?` <button class="btn primary sm" data-once onclick="confirmTransfer(${jsArg(x.id)})">Получил</button>`:''}</td></tr>`).join('')||`<tr><td colspan="9">${emptyState('Перемещений пока нет','','⇆')}</td></tr>`;const flow=document.querySelector('#transfers .flow');if(flow){flow.className='flow-steps';const c=s=>list.filter(x=>x.status===s).length;flow.innerHTML=[['Отправлено / в пути',c('В пути')],['Получено',c('Получено')]].map((s,i)=>`<div class="flow-step-card"><span class="step-n">${i+1}</span><div><b>${s[1]}</b><small>${s[0]}</small></div></div>`).join('<span class="flow-arrow">→</span>')}}

// ---------- Приход ----------
function renderReceipts(){const body=document.getElementById('receiptsBody');if(!body)return;const list=(opState.receipts||[]).filter(r=>currentUser?.role==='Super Admin'||allowedBranches().includes(r.branch));body.innerHTML=list.map(r=>{const exp=(r.items||[]).map(x=>x.expiry).filter(Boolean).sort()[0];const batches=(r.items||[]).map(x=>x.batch).filter(Boolean);return `<tr><td><b>${escH(r.id)}</b></td><td>${displayDate(r.time)}</td><td>${escH(r.branch)}</td><td>${escH(r.source)}</td><td><b>${(r.items||[]).length}</b></td><td>${batches.length?escH(batches[0]+(batches.length>1?' + ещё '+(batches.length-1):'')):'—'}</td><td>${exp?escH(new Date(exp).toLocaleDateString('ru-RU',{day:'2-digit',month:'2-digit'})):'—'}</td><td>${escH(r.user)}</td><td>${escH(r.doc||'—')}</td><td>${statusChip('Принято','green')}</td><td><button class="btn secondary sm" onclick="showReceiptDetails(${jsArg(r.id)})">Открыть</button></td></tr>`}).join('')||`<tr><td colspan="11">${emptyState('Приходов пока нет','Нажмите «Новый приход», чтобы принять товар.','↓')}</td></tr>`;const today=list.filter(r=>isTodayISO(r.time));const set=(i,v)=>{const e=document.getElementById(i);if(e)e.textContent=v};set('receiptTodayCount',today.length);set('receiptItemsCount',today.reduce((a,r)=>a+(r.items||[]).length,0));set('receiptLastTime',list[0]?new Date(list[0].time).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'}):'—')}
showReceiptDetails=function(id){const r=(opState.receipts||[]).find(x=>x.id===id);if(!r){toast('Приход не найден');return}showInfo('Приход '+r.id,`${r.branch} ← ${r.source} • ${displayDate(r.time)}`,`<div class="kv-list"><div><span>Принял</span><b>${escH(r.user)}</b></div><div><span>Документ</span><b>${escH(r.doc||'—')}</b></div>${r.comment?`<div><span>Комментарий</span><b>${escH(r.comment)}</b></div>`:''}</div><div class="table-wrap" style="margin-top:14px"><table class="compact"><thead><tr><th>Товар</th><th>Кол-во</th><th>Партия</th><th>Годен до</th></tr></thead><tbody>${(r.items||[]).map(x=>`<tr><td><b>${escH(x.product)}</b></td><td>${num(x.qty)} ${escH(x.unit)}</td><td>${escH(x.batch||'—')}</td><td>${x.expiry?escH(new Date(x.expiry).toLocaleString('ru-RU')):'—'}</td></tr>`).join('')}</tbody></table></div>`)};

// ---------- Цех ----------
function renderWarehouse(){const body=document.getElementById('warehouseBody');if(!body)return;const list=branchProducts('Цех');const open=(opState.requests||[]).filter(q=>REQ_OPEN.includes(q.status));const inBuy={};(opState.purchases||[]).filter(p=>['У снабженца','В пути'].includes(p.status)).forEach(p=>inBuy[p.product]=(inBuy[p.product]||0)+Number(p.qty||0));const reserve={};open.forEach(q=>reserve[q.product]=(reserve[q.product]||0)+Math.max(0,Number(q.qty)-Number(q.sent||0)));const f=document.getElementById('warehouseFilter')?.value||'need',s=(document.getElementById('warehouseSearch')?.value||'').toLowerCase();
 const rows=list.map(p=>{const bal=balanceOf('Цех',p.n),res=reserve[p.n]||0,lm=opState.limits?.['Цех']?.[p.n],red=Number(lm?.red||0),avail=bal-res,need=Math.max(0,-avail,red>0?red-avail:0),buy=inBuy[p.n]||0;return {p,bal,res,avail,need:num(need),buy}});
 const shown=rows.filter(r=>(f==='all'||r.res>0||r.need>0||r.buy>0)&&(!s||r.p.n.toLowerCase().includes(s)));const canBuy=can('purchases')||currentUser?.role==='Super Admin';
 body.innerHTML=shown.map(r=>`<tr class="${r.need>0?'low':''}"><td><b>${escH(r.p.n)}</b><div class="mini">${escH(r.p.c)}</div></td><td>${num(r.bal)} ${escH(r.p.u)}</td><td>${r.res?num(r.res)+' '+escH(r.p.u):'—'}</td><td class="${r.avail<0?'bad':''}"><b>${num(Math.max(0,r.avail))}</b></td><td class="${r.need>0?'bad':'good'}"><b>${r.need>0?num(r.need)+' '+escH(r.p.u):'0'}</b></td><td>${r.buy?num(r.buy)+' '+escH(r.p.u):'—'}</td><td>${r.need>r.buy&&canBuy?`<button class="btn danger sm" onclick="startPurchase(${jsArg(r.p.n)},${num(r.need-r.buy)},'Дефицит по заявкам филиалов')">В закупку</button>`:r.need>0?'<span class="mini">закуп оформлен</span>':'—'}</td></tr>`).join('')||`<tr><td colspan="7">${emptyState(f==='need'?'Всё в порядке':'Ничего не найдено',f==='need'?'Нет дефицита и открытого резерва. Переключите фильтр на «Все позиции».':'')}</td></tr>`;
 const deficit=rows.filter(r=>r.need>0).length,activeBuy=(opState.purchases||[]).filter(p=>['У снабженца','В пути'].includes(p.status)).length,transit=(opState.transfers||[]).filter(t=>t.from==='Цех'&&t.status==='В пути').length;
 const k=document.getElementById('warehouseKpis');if(k)k.innerHTML=`<div class="card kpi dash-click" onclick="document.getElementById('warehouseFilter').value='all';renderWarehouse()"><div class="kpi-label">Позиций в каталоге цеха</div><div class="kpi-val">${list.length}</div><div class="delta">${rows.filter(r=>r.bal>0).length} в наличии</div></div><div class="card kpi dash-click" onclick="showPage('requests')"><div class="kpi-label">Открытые заявки филиалов</div><div class="kpi-val warn">${open.length}</div><div class="delta">ждут комплектации / отправки</div></div><div class="card kpi"><div class="kpi-label">Дефицит</div><div class="kpi-val ${deficit?'bad':'good'}">${deficit}</div><div class="delta">позиций не хватает под заявки</div></div><div class="card kpi dash-click" onclick="showPage('purchases')"><div class="kpi-label">Закупы в работе</div><div class="kpi-val">${activeBuy}</div><div class="delta">в пути с цеха: ${transit}</div></div>`}

// ---------- Инвентаризация ----------
function invIndexMap(b){const m={};branchProducts(b).forEach((p,i)=>m[p.n]=i);return m}
function renderInventoryTableV20(){const body=document.getElementById('inventoryBody');if(!body)return;const b=activeBranchName(),active=inventorySessions[b]?.status==='Активна',mgr=isBranchManagerFor(b),list=filteredProducts('inventory'),idx=invIndexMap(b),onlyEmpty=document.getElementById('invOnlyEmpty')?.checked;const head=document.getElementById('inventoryHead');if(head)head.innerHTML=mgr?'<tr><th>Продукт</th><th>Ед.</th><th class="num-col">По системе</th><th>Факт</th><th class="num-col">Разница</th><th class="num-col">Сумма</th><th>Комментарий</th><th>Статус</th></tr>':'<tr><th>Продукт</th><th>Ед.</th><th>Фактическое количество</th><th>Комментарий</th><th>Статус</th></tr>';
 const sel=document.getElementById('inventoryBranchSelect');if(sel){const opts=allowedSelectOptions(true);sel.innerHTML=opts.map(x=>`<option ${x===b?'selected':''}>${escH(x)}</option>`).join('')}
 let last='';const cols=mgr?8:5;const rows=[];list.forEach(p=>{const e=inventoryEntry(b,p.n),filled=e.fact!==''&&e.fact!==null&&e.fact!==undefined;if(onlyEmpty&&filled)return;if(p.c!==last){last=p.c;rows.push(`<tr class="category-row"><td colspan="${cols}">${escH(p.c)}</td></tr>`)}const bA=jsArg(b),nA=jsArg(p.n);const input=`<input class="inventory-row-input" inputmode="decimal" type="number" step="0.001" min="0" placeholder="факт" value="${escH(e.fact??'')}" ${active?'':'disabled'} oninput="invInput(this,${bA},${nA})">`;const comment=`<input class="inv-comment" placeholder="Комментарий" value="${escH(e.comment||'')}" ${active?'':'disabled'} oninput="saveInventoryValue(${bA},${nA},'comment',this.value)">`;const st=`<span class="status ${filled?'green':active?'yellow':'blue'}" data-inv-status>${filled?'Заполнено':active?'Ожидает':'Закрыто'}</span>`;if(mgr){const sys=balanceOf(b,p.n),cost=demoLedgerFor(b,p,idx[p.n]||0).cost,diff=filled?num(Number(e.fact)-sys):null;rows.push(`<tr data-sys="${sys}" data-cost="${cost}"><td><b>${escH(p.n)}</b></td><td>${escH(p.u)}</td><td class="num-col">${num(sys)}</td><td>${input}</td><td class="num-col" data-inv-diff>${diffCell(diff)}</td><td class="num-col" data-inv-sum>${sumCell(diff,cost)}</td><td>${comment}</td><td>${st}</td></tr>`)}else rows.push(`<tr><td><b>${escH(p.n)}</b></td><td>${escH(p.u)}</td><td>${input}</td><td>${comment}</td><td>${st}</td></tr>`)});
 body.closest('table')?.classList.toggle('inv-mgr',mgr);body.closest('table')?.classList.toggle('inv-staff',!mgr);body.innerHTML=rows.join('')||`<tr><td colspan="${cols}">${emptyState(onlyEmpty?'Все позиции заполнены':'Ничего не найдено',onlyEmpty?'Можно завершать инвентаризацию.':'Измените поиск или категорию.','✓')}</td></tr>`;updateInvProgress(b)}
function diffCell(d){return '<div class="cv">'+diffCellRaw(d)+'</div>'}
function diffCellRaw(d){if(d===null)return '<span class="mini">—</span>';if(Math.abs(d)<.0001)return '<span class="good">0</span>';return `<b class="${d<0?'bad':'info'}">${d>0?'+':''}${d}</b><div class="mini">${d<0?'недостача':'излишек'}</div>`}
function sumCell(d,cost){return '<div class="cv">'+sumCellRaw(d,cost)+'</div>'}
function sumCellRaw(d,cost){if(d===null||Math.abs(d)<.0001)return '—';const a=Math.round(d*cost);return `<span class="${a<0?'bad':'info'}">${a>0?'+':''}${a.toLocaleString('ru-RU')}</span>`}
function invInput(el,b,n){saveInventoryValue(b,n,'fact',el.value);const tr=el.closest('tr');if(!tr)return;const filled=el.value!=='';const st=tr.querySelector('[data-inv-status]');if(st){st.className='status '+(filled?'green':'yellow');st.textContent=filled?'Заполнено':'Ожидает'}if(tr.dataset.sys!==undefined){const d=filled?num(Number(el.value)-Number(tr.dataset.sys)):null;tr.querySelector('[data-inv-diff]').innerHTML=diffCell(d);tr.querySelector('[data-inv-sum]').innerHTML=sumCell(d,Number(tr.dataset.cost))}updateInvProgress(b)}
function updateInvProgress(b){const total=branchProducts(b).length,d=inventoryDrafts[b]||{},done=Object.values(d).filter(x=>x&&x.fact!==''&&x.fact!=null&&!Number.isNaN(Number(x.fact))).length;const pr=document.getElementById('inventoryProgress');if(pr){pr.className='inv-progress';pr.innerHTML=`<span class="inv-progress-bar"><i style="width:${total?done/total*100:0}%"></i></span><b>${done} из ${total}</b>`}}
saveInventoryValue=function(branch,name,field,value){inventoryDrafts[branch]??={};inventoryDrafts[branch][name]??={fact:'',comment:''};inventoryDrafts[branch][name][field]=value;const done=Object.values(inventoryDrafts[branch]).filter(x=>x.fact!==''&&x.fact!==null&&!Number.isNaN(Number(x.fact))).length;if(inventorySessions[branch]){inventorySessions[branch].progress=done;if(field==='fact')inventorySessions[branch].user=currentUser?.name||'Сотрудник'}const i=branches.findIndex(x=>x[0]===branch);if(i>=0)branches[i][1]=done;debouncedSave()};
fillDemoInventory=function(){if(currentUser?.role!=='Super Admin'){toast('Демо-заполнение доступно только IT-отделу');return}const b=activeInventoryBranch();if(!b){toast('Сначала запустите день инвентаризации для филиала');return}const list=branchProducts(b);inventoryDrafts[b]??={};list.forEach((p,i)=>{const sys=balanceOf(b,p.n);let delta=0;if(i%10===0)delta=-(p.u==='шт'?2:.5);else if(i%14===0)delta=(p.u==='шт'?3:.7);inventoryDrafts[b][p.n]={fact:Math.max(0,num(sys+delta)),comment:delta<0?'Тест: недостача':delta>0?'Тест: излишек':''}});inventorySessions[b].progress=list.length;inventorySessions[b].user=currentUser?.name||'Сотрудник';const bi=branches.findIndex(x=>x[0]===b);if(bi>=0)branches[bi][1]=list.length;saveOperationalState();renderProductTables();toast('Демо: факт заполнен для '+list.length+' позиций')};
const _finishInventoryV19=finishInventory;
finishInventory=async function(){const b=activeInventoryBranch();if(!b||!inventorySessions[b]){toast('Активный день инвентаризации для вашего филиала не найден');return}if(!isBranchManagerFor(b)){toast('Завершить инвентаризацию может только менеджер этого филиала или Super Admin');return}const total=branchProducts(b).length,d=inventoryDrafts[b]||{},done=Object.values(d).filter(x=>x&&x.fact!==''&&x.fact!=null).length;if(done<total){toast(`Не заполнено позиций: ${total-done}. Включите «Только незаполненные», чтобы найти их.`);return}const ok=await confirmDialog({title:'Завершить инвентаризацию '+b+'?',text:`Заполнено ${done} из ${total}. После завершения системные остатки будут заменены фактическими, а результат уйдёт в «Сверку остатков». Отменить это действие нельзя.`,okText:'Завершить'});if(!ok)return;const prevAt=inventoryResults[b]?.completedAt+'|'+inventoryResults[b]?.rows?.length;_finishInventoryV19();const res=inventoryResults[b];if(!res||inventorySessions[b]?.status!=='Завершена')return;showInventorySummary(b)};
function showInventorySummary(b){const res=inventoryResults[b];if(!res)return;const rows=res.rows||[],short=rows.filter(r=>r.diff<0),over=rows.filter(r=>r.diff>0),match=rows.length-short.length-over.length,shortSum=short.reduce((a,r)=>a+r.amount,0),overSum=over.reduce((a,r)=>a+r.amount,0);const top=[...short].sort((a,b)=>a.amount-b.amount).slice(0,5);showInfo('Инвентаризация завершена • '+b,`${res.date} • ${res.completedAt} • ${res.user}`,`<div class="inv-summary"><div class="sum-tile"><small>Позиций</small><b>${rows.length}</b></div><div class="sum-tile good"><small>Совпало</small><b>${match}</b></div><div class="sum-tile bad"><small>Недостача</small><b>${short.length}</b><span>${shortSum<0?money(shortSum):'—'}</span></div><div class="sum-tile info"><small>Излишек</small><b>${over.length}</b><span>${overSum>0?'+'+money(overSum):'—'}</span></div></div><div class="note-box ${shortSum+overSum<0?'bad':''}"><b>Чистое отклонение: ${(shortSum+overSum>0?'+':'')+money(shortSum+overSum)}</b><div class="mini">Системные остатки обновлены фактом.</div></div>${top.length?`<div class="small-label" style="margin:14px 0 8px">Крупнейшие недостачи</div><div class="kv-list">${top.map(r=>`<div><span>${escH(r.product)}</span><b class="bad">${r.diff} ${escH(r.unit)} • ${money(r.amount)}</b></div>`).join('')}</div>`:''}`,`<button class="btn primary" onclick="closeModal('infoModal');const s=document.getElementById('reconcileBranch');if(s){if(![...s.options].some(o=>o.value===${jsArg(b)}))s.insertAdjacentHTML('beforeend','<option>'+${jsArg(b)}+'</option>');s.value=${jsArg(b)}};showPage('reconcile')">Открыть сверку</button>`)}
const _updateInventoryUserBannerV19=updateInventoryUserBanner;
updateInventoryUserBanner=function(){_updateInventoryUserBannerV19();const banner=document.getElementById('inventoryActiveBanner');if(!banner)return;const b=activeInventoryBranch();if(b){const s=inventorySessions[b],mgr=isBranchManagerFor(b),total=branchProducts(b).length;banner.className='card panel inv-banner active';banner.innerHTML=`<div class="inv-banner-row"><div><span class="status yellow">● Идёт инвентаризация</span><h3>${escH(b)}</h3><div class="mini">${escH(inventoryDayMeta.title||'Инвентаризация')} • ${escH(inventoryDayMeta.date||'')} • запущено ${escH(s.startedAt||'')}${inventoryDayMeta.note?' • '+escH(inventoryDayMeta.note):''}</div></div><div class="inv-steps"><div class="${s.progress>0?'done':''}"><span>1</span>Посчитайте товар</div><div class="${s.progress>=total?'done':''}"><span>2</span>Введите факт</div><div><span>3</span>${mgr?'Завершите':'Менеджер завершит'}</div></div></div><div class="mini" style="margin-top:8px">${mgr?'Вы видите остаток по системе и разницу. Сотрудники видят только поле «Факт».':'Вводите только фактическое количество — всё сохраняется автоматически.'}</div>`}else{banner.className='card panel inv-banner';banner.innerHTML=emptyState('Нет активной инвентаризации','Инвентаризацию запускает IT-отдел / Super Admin в разделе «День инвентаризации».','☑')}};
const _renderProductTablesV19=renderProductTables;
renderProductTables=function(){try{_renderProductTablesV19()}catch(e){console.error('product tables',e)}safeRun('inventory table',renderInventoryTableV20);const st=document.querySelector('#stockTable tbody');if(st&&!st.innerHTML.trim())st.innerHTML=`<tr><td colspan="9">${emptyState('Товары не найдены','Измените поиск или категорию.')}</td></tr>`};
function setupInventoryFilters(){const f=document.querySelector('#inventory .filters');if(f&&!document.getElementById('invOnlyEmpty'))f.insertAdjacentHTML('beforeend','<label class="switch filter-check"><input type="checkbox" id="invOnlyEmpty" onchange="renderInventoryTableV20()"> Только незаполненные</label>')}

// ---------- Филиал (детальная страница) ----------
const _openBranchV19=openBranch;
openBranch=function(i){_openBranchV19(i);const b=branches[i]?.[0];if(!b)return;safeRun('branch detail',()=>{const today=(opState.sales||[]).filter(x=>x.branch===b&&isTodayISO(x.time)).reduce((a,x)=>a+Number(x.amount||0),0);document.getElementById('bdSales').textContent=b==='Цех'?'—':ceoMoneyShort(today)+' сум';let crit=0;Object.entries(opState.limits?.[b]||{}).forEach(([p,lm])=>{if(Number(lm?.red)>0&&balanceOf(b,p)<Number(lm.red))crit++});const ce=document.getElementById('bdCritical');ce.textContent=crit;ce.className='kpi-val '+(crit?'bad':'good');const s=inventorySessions[b];document.getElementById('bdInventory').textContent=s?`${s.status} • ${s.progress}/${branchProducts(b).length}`:'Не запущена';const mv=(opState.audit||[]).filter(x=>x.branch===b&&x.product).slice(0,12);document.getElementById('branchDetailMoves').innerHTML=mv.map(x=>`<tr><td>${displayDate(x.time)}</td><td><b>${escH(x.action)}</b></td><td>${escH(x.product)}</td><td class="${x.qty>0?'good':x.qty<0?'bad':''}">${x.qty>0?'+':''}${num(x.qty)}</td><td>${escH(x.user)}</td></tr>`).join('')||`<tr><td colspan="5">${emptyState('Движений пока нет','Приходы, продажи и списания появятся здесь.')}</td></tr>`;document.querySelectorAll('#branchDetail .tabs .tab').forEach(t=>{const m=String(t.getAttribute('onclick')||'').match(/showPage\('(\w+)'\)/);if(m)t.style.display=can(m[1])?'':'none'})})};

// ---------- Dashboard ----------
renderDashboardOperational=function(){const root=document.getElementById('dashboardDynamic');if(!root||!currentUser)return;const sa=currentUser.role==='Super Admin';const visibleBranches=(sa?branches.map(b=>b[0]):allowedBranches()).filter(b=>b!=='Цех');const crit=[];const scan=sa||allowedBranches().includes('Цех')?visibleBranches.concat(['Цех']):visibleBranches;scan.forEach(branch=>Object.entries(opState.limits?.[branch]||{}).forEach(([p,lm])=>{const bal=balanceOf(branch,p);if(Number(lm?.red)>0&&bal<Number(lm.red))crit.push({branch,product:p,balance:bal,limit:Number(lm.red),unit:unitFor(branch,p)})}));
 const todaySales=(opState.sales||[]).filter(x=>visibleBranches.includes(x.branch)&&isTodayISO(x.time)),salesSum=todaySales.reduce((a,x)=>a+Number(x.amount||0),0);const openReq=(opState.requests||[]).filter(x=>(sa||visibleBranches.includes(x.branch)||allowedBranches().includes('Цех'))&&requestStage(x)!=='Принято');const toAccept=(opState.transfers||[]).filter(x=>x.status==='В пути'&&(sa||allowedBranches().includes(x.to)));let shortRows=[];visibleBranches.forEach(b=>(inventoryResults[b]?.rows||[]).filter(x=>x.diff<0).forEach(x=>shortRows.push({...x,branch:b})));const shortSum=Math.abs(shortRows.reduce((a,x)=>a+Number(x.amount||0),0));const invActive=visibleBranches.filter(b=>inventorySessions[b]?.status==='Активна');const tasksReview=(opState.tasks||[]).filter(t=>t.status==='На проверке'&&taskCanReview(t)).length;const supportOpen=sa?(opState.supportTickets||[]).filter(t=>t.status!=='Решено').length:0;const activePurch=(opState.purchases||[]).filter(x=>['У снабженца','В пути'].includes(x.status)).length;
 const att=[];if(crit.length)att.push(['red','Критические остатки: '+crit.length,crit.slice(0,2).map(c=>c.product+' ('+c.branch+')').join(', ')+(crit.length>2?' и др.':''),"showPage('stock')",'Открыть остатки']);if(toAccept.length)att.push(['yellow','Товар в пути к вам: '+toAccept.length,'Подтвердите получение, чтобы остатки обновились.',"showPage('transfers')",'Принять']);if(openReq.length&&(sa||allowedBranches().includes('Цех')))att.push(['yellow','Открытые заявки филиалов: '+openReq.length,'Заявки ждут комплектации или отправки.',"showPage('requests')",'К заявкам']);if(invActive.length)att.push(['blue','Идёт инвентаризация: '+invActive.join(', '),'Следите за прогрессом и завершите после заполнения.',can('inventoryDay')?"showPage('inventoryDay')":"showPage('inventory')",'Открыть']);if(tasksReview)att.push(['yellow','Отчёты по заданиям на проверке: '+tasksReview,'Примите или верните отчёты сотрудников.',"showPage('tasks')",'Проверить']);if(shortRows.length)att.push(['red','Недостача по сверке: '+money(shortSum),shortRows.length+' позиций с недостачей.',"showPage('reconcile')",'Сверка']);if(supportOpen)att.push(['blue','Обращения в IT: '+supportOpen,'Нерешённые обращения сотрудников.',"showPage('support')",'Ответить']);
 const branchRows=visibleBranches.map(branch=>{const bs=(opState.sales||[]).filter(x=>x.branch===branch&&isTodayISO(x.time)).reduce((a,x)=>a+Number(x.amount||0),0);const bc=crit.filter(c=>c.branch===branch).length;const req=openReq.filter(x=>x.branch===branch).length;const inv=inventorySessions[branch];return `<tr class="dash-click-row" onclick="openBranch(branches.findIndex(b=>b[0]===${jsArg(branch)}))"><td><b>${escH(branch)}</b></td><td>${statusChip(inv?.status||'Не запущена',inv?.status==='Активна'?'yellow':inv?.status==='Завершена'?'green':'blue')}</td><td class="num-col">${money(bs)}</td><td class="${bc?'bad':'good'}"><b>${bc}</b></td><td>${req}</td><td class="row-go">→</td></tr>`}).join('');
 const recent=(opState.audit||[]).filter(x=>sa||visibleBranches.includes(x.branch)||allowedBranches().includes(x.branch)).slice(0,8);
 root.innerHTML=`<div class="page-head"><div><h1>${sa?'Обзор системы':currentUser.role==='Управляющий сетью'?'Обзор сети':'Обзор филиала'}</h1><div class="subtitle">Что сегодня требует внимания • ${new Date().toLocaleDateString('ru-RU',{weekday:'long',day:'numeric',month:'long'})}</div></div>${can('audit')?`<button class="btn secondary" onclick="exportAudit()">⇩ История Excel</button>`:''}</div>
 <div class="card panel attention-card"><div class="dash-section-head"><h3>Требует внимания</h3><span class="mini">${att.length?att.length+' пунктов':''}</span></div>${att.length?`<div class="attention-list">${att.map(a=>`<div class="attention-item ${a[0]}" onclick="${a[3]}"><span class="att-dot"></span><div><b>${escH(a[1])}</b><div class="mini">${escH(a[2])}</div></div><button class="btn secondary sm" tabindex="-1">${a[4]}</button></div>`).join('')}</div>`:emptyState('Всё спокойно','Срочных задач нет.','✓')}</div>
 <div class="grid kpis"><div class="card kpi dash-click" onclick="showPage('sales')"><div class="kpi-label">Продажи сегодня</div><div class="kpi-val">${ceoMoneyShort(salesSum)} <small>сум</small></div><div class="delta">${todaySales.length} заказов</div></div><div class="card kpi dash-click" onclick="showPage('stock')"><div class="kpi-label">Критические остатки</div><div class="kpi-val ${crit.length?'bad':'good'}">${crit.length}</div><div class="delta">ниже красного лимита</div></div><div class="card kpi dash-click" onclick="showPage('requests')"><div class="kpi-label">Заявки в работе</div><div class="kpi-val ${openReq.length?'warn':''}">${openReq.length}</div><div class="delta">в пути: ${toAccept.length}</div></div><div class="card kpi dash-click" onclick="showPage('purchases')"><div class="kpi-label">Закупы в работе</div><div class="kpi-val">${activePurch}</div><div class="delta">у снабженца / в пути</div></div></div>
 <div class="grid split"><div class="card panel"><div class="dash-section-head"><h3>Филиалы</h3>${can('staffStructure')?`<button class="btn secondary sm" onclick="showPage('staffStructure')">Оргструктура →</button>`:''}</div><div class="table-wrap"><table class="compact"><thead><tr><th>Филиал</th><th>Инвентаризация</th><th class="num-col">Продажи сегодня</th><th>Критично</th><th>Заявки</th><th></th></tr></thead><tbody>${branchRows||`<tr><td colspan="6">${emptyState('Нет филиалов','')}</td></tr>`}</tbody></table></div></div><div class="card panel"><div class="dash-section-head"><h3>Критические остатки</h3></div><div class="alert-list">${crit.slice(0,5).map(x=>`<div class="alert"><div class="ico">!</div><div><b>${escH(x.product)}</b><p>${escH(x.branch)} • ${num(x.balance)} ${escH(x.unit)} при лимите ${num(x.limit)}</p></div></div>`).join('')||emptyState('Критических остатков нет','Лимиты задаются в разделе «Остатки».','✓')}</div></div></div>
 <div class="card panel" style="margin-top:16px"><div class="dash-section-head"><div><h3>Последние действия</h3><div class="mini">Приходы, продажи, списания, перемещения, закупы</div></div>${can('audit')?`<button class="btn secondary sm" onclick="showPage('audit')">Вся история →</button>`:''}</div><div class="table-wrap"><table class="compact"><thead><tr><th>Время</th><th>Филиал</th><th>Действие</th><th>Объект</th><th>Пользователь</th></tr></thead><tbody>${recent.map(x=>`<tr><td>${displayDate(x.time)}</td><td>${escH(x.branch)}</td><td><b>${escH(x.action)}</b></td><td>${escH(x.object)}</td><td>${escH(x.user)}</td></tr>`).join('')||`<tr><td colspan="5">${emptyState('История пока пустая','')}</td></tr>`}</tbody></table></div></div>`};

// ---------- Отчёты ----------
function renderReportsGrid(){const g=document.getElementById('reportsGrid');if(!g)return;const sa=currentUser?.role==='Super Admin';const R=[['ceo','CEO отчёт','Сводка периода, филиалы, расходы, центр платежей','exportCEOReport()'],['financeData','Все финансы компании','Деньги, долги, доходы, расходы, зарплаты, аренда','exportAllCompanyFinance()'],['financeData','Финансовые записи','Записи за выбранный период с итогами по типам','exportFinanceData()'],['financeData','Зарплаты','Начисления, авансы, выплаты и остатки','exportSalaryReport()'],['financeData','Аренда','Договоры, начисления, оплаты и долги','exportRentReport()'],['sales','Продажи','Чеки, товары, способы оплаты, итоги','exportSales()'],['reconcile','Сверка остатков','Недостача, излишки, сумма отклонения','exportReconcile()'],['audit','Движение продукции','Приход, перемещения, продажи, списания','exportMovements()'],['audit','История действий','Полный журнал пользователей и операций','exportAudit()'],['purchases','Закупки','Закупы цеха, поставщики, статусы','exportPurchases()'],['equipment','Оборудование','Состояние оборудования по филиалам','exportEquipment()'],['tasks','Задания','Задания сотрудникам и отчёты','exportTasks()'],['__it','Техподдержка','Обращения сотрудников и статусы','exportSupportTickets()']];const list=R.filter(r=>r[0]==='__it'?sa:(r[0]==='financeData'&&r[1]==='Все финансы компании'?(can('financeData')||can('ceo')):can(r[0])));g.innerHTML=list.map(r=>`<div class="card report-card"><div class="report-ico">⇩</div><div><h3>${escH(r[1])}</h3><p class="mini">${escH(r[2])}</p></div><button class="btn secondary" onclick="${r[3]}">Скачать Excel</button></div>`).join('')||`<div class="card panel">${emptyState('Нет доступных отчётов','')}</div>`}

// ---------- Оргструктура: сотрудники рядами под филиалом (без наложений) ----------
staffArcPositions=function(branch,x,y,count){if(count<=0)return[];const gap=138,perRow=branch==='Cyber Arena'?5:4,out=[];const rows=Math.ceil(count/perRow);for(let r=0;r<rows;r++){const n=Math.min(perRow,count-r*perRow);let start=x-(n-1)*gap/2;const min=72,max=1320-72;if(start<min)start=min;if(start+(n-1)*gap>max)start=max-(n-1)*gap;for(let i=0;i<n;i++)out.push({x:Math.round(start+i*gap),y:Math.round(y+175+r*150)})}return out};
// ---------- Оргструктура: только рабочие действия ----------
const _renderOrgFocusPanelV19=renderOrgFocusPanel;
renderOrgFocusPanel=function(){_renderOrgFocusPanelV19();const p=document.getElementById('orgNodeModalContent');if(!p)return;p.querySelectorAll('.action-btn').forEach(btn=>{const oc=btn.getAttribute('onclick')||'';const m=oc.match(/showPage\('(\w+)'\)/);if(m&&!can(m[1])){btn.remove();return}if(/toast\('Создание закупа'\)/.test(oc)){if(can('purchases'))btn.setAttribute('onclick',"closeModal('orgNodeModal');startPurchase()");else btn.remove();return}if(/toast\('Карточка поставщиков'\)/.test(oc)){btn.remove();return}if(/toast\('Карточка сотрудника/.test(oc)){const s=currentOrgSelection;const u=users.find(x=>x.login===s.login);if(currentUser?.role==='Super Admin'&&u)btn.setAttribute('onclick',`closeModal('orgNodeModal');editUser(${u.id})`);else btn.remove()}});p.querySelectorAll('.action-grid').forEach(g=>{if(!g.children.length)g.remove()})};

// ---------- Техподдержка: IT-фильтры и непрочитанные ----------
function supportUnreadForIT(t){return (t.messages||[]).some(m=>m.by!=='it'&&!m.readByIT)}
supportFilteredTickets=function(){if(!currentUser)return[];const it=isITUser(),q=(document.getElementById('supportSearch')?.value||'').toLowerCase(),st=document.getElementById('supportStatusFilter')?.value||'Все статусы',cat=it?document.getElementById('supportCategoryFilter')?.value||'Все категории':'Все категории',pr=it?document.getElementById('supportPriorityFilter')?.value||'Любой приоритет':'Любой приоритет',unread=it&&document.getElementById('supportUnreadOnly')?.checked;return (opState.supportTickets||[]).filter(t=>supportTicketVisible(t)&&(st==='Все статусы'||t.status===st)&&(cat==='Все категории'||t.category===cat)&&(pr==='Любой приоритет'||t.priority===pr)&&(!unread||supportUnreadForIT(t))&&(!q||(t.subject+' '+t.creatorName+' '+t.branch+' '+t.number+' '+t.category).toLowerCase().includes(q))).sort((a,b)=>new Date(b.updatedAt)-new Date(a.updatedAt))};
const _selectSupportTicketV19=selectSupportTicket;
selectSupportTicket=function(id){const t=opState.supportTickets.find(x=>x.id===Number(id));if(t&&isITUser()){(t.messages||[]).forEach(m=>{if(m.by!=='it')m.readByIT=true});saveOperationalState()}_selectSupportTicketV19(id);if(window.innerWidth<=980)document.getElementById('supportChatPanel')?.scrollIntoView({behavior:'smooth',block:'start'})};
updateSupportBadge=function(){const el=document.getElementById('supportNavBadge');if(!el||!currentUser)return;const n=isITUser()?(opState.supportTickets||[]).filter(t=>t.status!=='Решено'&&(t.status==='Новое'||supportUnreadForIT(t))).length:(opState.supportTickets||[]).filter(t=>supportTicketVisible(t)&&t.messages?.some(m=>m.by==='it'&&!m.readByEmployee)).length;el.textContent=n;el.style.display=n?'inline-block':'none'};
const _renderSupportV19=renderSupport;
renderSupport=function(){const f=document.getElementById('supportItFilters');if(f)f.style.display=isITUser()?'flex':'none';_renderSupportV19();if(isITUser())document.querySelectorAll('#supportTicketList .support-ticket').forEach(el=>{const id=Number((el.getAttribute('onclick')||'').match(/\d+/)?.[0]);const t=opState.supportTickets.find(x=>x.id===id);if(t&&supportUnreadForIT(t)){el.classList.add('unread');const title=el.querySelector('.support-ticket-title');if(title&&!title.querySelector('.unread-dot'))title.insertAdjacentHTML('afterbegin','<span class="unread-dot" title="Есть непрочитанные"></span>')}})};

// ---------- Быстрый выбор филиала: только доступные ----------
renderBranchQuick=function(containerId,selectId,selected,renderFn,allValue){const el=document.getElementById(containerId);if(!el)return;const all=allValue||'Все филиалы';const own=isTop()?chartBranches():allowedBranches().filter(b=>b!=='Цех');if(own.length<2){el.innerHTML='';el.style.display='none';return}el.style.display='';const opts=[all,...own];el.innerHTML='<span class="mini" style="align-self:center;margin-right:3px"><b>Филиал:</b></span>'+opts.map(b=>`<button class="chart-branch-btn ${b===selected?'active':''}" onclick="setChartBranch(${jsArg(selectId)},${jsArg(b)},${jsArg(renderFn)})">${escH(b)}</button>`).join('')};
// ---------- Приход: позиции без перерисовки (фокус не теряется) ----------
setReceiptItem=function(i,k,v){if(!receiptDraftItems[i])return;receiptDraftItems[i][k]=v;if(k==='product'){const u=receiptUnitFor(v);receiptDraftItems[i].unit=u;const sel=document.querySelectorAll('#receiptItemsBody tr')[i]?.querySelector('select');if(sel)sel.value=u}};
// ---------- Касса: позиции продажи ----------
function saleProductChanged(el,i){if(!saleDraftItems[i])return;saleDraftItems[i].product=el.value.trim();saleDraftItems[i].unit=unitFor(document.getElementById('saleBranch')?.value||activeBranchName(),saleDraftItems[i].product);const u=el.closest('tr')?.querySelector('td.mini');if(u)u.textContent=saleDraftItems[i].unit}
renderSaleItems=function(){const b=document.getElementById('saleItemsBody');if(!b)return;b.innerHTML=saleDraftItems.map((x,i)=>`<tr><td><input list="productCatalogList" placeholder="Товар — начните вводить" value="${escH(x.product)}" onchange="saleProductChanged(this,${i})"></td><td><input type="number" inputmode="decimal" min="0" step="0.001" placeholder="Кол-во" value="${escH(x.qty)}" oninput="saleDraftItems[${i}].qty=this.value"></td><td class="mini">${escH(x.unit)}</td><td><button class="btn secondary" title="Убрать позицию" onclick="removeSaleItem(${i})">✕</button></td></tr>`).join('')};
const _startSaleV19=startSale;startSale=function(){_startSaleV19();safeRun('sale catalog',()=>syncProductControlsFor(document.getElementById('saleBranch')?.value||activeBranchName()));const sb=document.getElementById('saleBranch');if(sb&&!sb.dataset.v20){sb.dataset.v20='1';sb.addEventListener('change',()=>syncProductControlsFor(sb.value))}};
// ---------- Таблицы → карточки на телефоне ----------
const STACK_BODIES=['requestsBody','transfersBody','purchasesBody','receiptsBody','writeoffsBody','salesBody','financeBody','salaryBody','auditBody','equipmentBody','warehouseBody','inventoryBody','productHistoryBody','inventoryDayBody','branchDetailMoves'];
function autoStackTables(){STACK_BODIES.forEach(id=>document.getElementById(id)?.closest('table')?.classList.add('stack-table'));['#reconcileTable','#stockTable'].forEach(s=>document.querySelector(s)?.classList.add('stack-table'));document.querySelectorAll('table.stack-table').forEach(tb=>{const heads=[...tb.querySelectorAll('thead th')].map(th=>th.textContent.trim());tb.querySelectorAll('tbody tr').forEach(tr=>{if(tr.dataset.stacked===String(heads.length))return;[...tr.children].forEach((td,i)=>{if(td.hasAttribute('colspan'))return;td.setAttribute('data-label',heads[i]||'');if(!td.querySelector(':scope>.cv')&&td.childNodes.length){const w=document.createElement('div');w.className='cv';while(td.firstChild)w.appendChild(td.firstChild);td.appendChild(w)}});tr.dataset.stacked=String(heads.length)})})}
let v20StackTimer=null;function scheduleStack(){clearTimeout(v20StackTimer);v20StackTimer=setTimeout(()=>safeRun('stack',autoStackTables),30)}
safeRun('stack observer',()=>new MutationObserver(scheduleStack).observe(document.querySelector('.content'),{childList:true,subtree:true}));
// ---------- Обёртки: операционные таблицы ----------
const _renderOperationalTablesV19=renderOperationalTables;
renderOperationalTables=function(){try{_renderOperationalTablesV19()}catch(e){console.error('op tables',e)}safeRun('requests',renderRequestsV20);safeRun('transfers',renderTransfersV20);safeRun('purchases',renderPurchasesV20);safeRun('receipts',renderReceipts);if(currentPageId()==='warehouse')safeRun('warehouse',renderWarehouse);safeRun('badges',updateNavBadges);const ab=document.getElementById('auditBody');if(ab&&/История пока пуста/.test(ab.textContent))ab.innerHTML=`<tr><td colspan="7">${emptyState('История пока пуста','Все действия сотрудников будут появляться здесь.')}</td></tr>`;const ab2=document.getElementById('auditBranchFilter');if(ab2&&!ab2.dataset.v20){ab2.dataset.v20='1';const old=ab2.value;ab2.innerHTML='<option>Все филиалы</option>'+branches.map(b=>`<option>${escH(b[0])}</option>`).join('')+'<option>—</option>';ab2.value=old||'Все филиалы'}};
const _renderV19=render;
render=function(){try{_renderV19()}catch(e){console.error('render core',e);safeRun('op',renderOperationalTables)}if(currentPageId()==='warehouse')safeRun('warehouse',renderWarehouse)};
